/// <summary>
/// Extension class for SalesTable form.
/// Adds click handler logic for the custom button METUpdateAdhocOrder.
/// </summary>
[ExtensionOf(formControlStr(SalesTable, METUpdateAdhocOrder))]
final class METSalesTableForm_METUpdateAdhocOrder_Extension
{
}

Method.Source:
 /// <summary>
 /// Click handler for the custom "Update adhoc order" button on the SalesTable form.
 /// </summary>
public void clicked()
{
    next clicked();

    FormControl control = this;
    FormDataSource salesTableDS = control.formRun().dataSource(formDataSourceStr(SalesTable, SalesTable));
    SalesTable salesTable = salesTableDS.cursor();

    DialogButton result = Box::yesNo("@MET:UpdateAdhocOrderConfirmMsg", DialogButton::No);

    if (result == DialogButton::Yes)
    {
        ttsBegin;
        METSalesTable metSalesTable = METSalesTable::findBySalesId(salesTable.SalesId, true);
        metSalesTable.AdhocOrder = metSalesTable.AdhocOrder == NoYes::Yes ? NoYes::No : NoYes::Yes;
        metSalesTable.update();
        ttsCommit;

        FormDataSource metSalesTableDS = control.formRun().dataSource(formDataSourceStr(SalesTable, MetSalesTable));
        metSalesTableDS.reread();
        metSalesTableDS.refresh();
    }
}
